import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

/** @typedef {import('three/webgpu').Texture} Texture */
/** @typedef {import('three/webgpu').Material} Material */
/** @typedef {import('three/webgpu').Geometry} Geometry */

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  /** @type {any[]} */
  const _primitives = [];

  // root container for this node
  const root = new Group();
  root.name = config.id ?? 'collection-card-1';

  // ---- Geometry & Material -------------------------------------------------
  const width = 7; // default width, can be adjusted per design
  const height = 6; // default height

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  const plane = new Mesh(geometry, material);
  plane.name = 'card-plane';
  root.add(plane);

  // ---- Load Texture --------------------------------------------------------
  let _texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      _texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---- Apply Cinematic Primitives -----------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const name = prim.name;
      const params = prim.params || {};
      // Ensure the primitive exists in the provided map
      if (typeof ctx.primitives[name] === 'function') {
        const instance = ctx.primitives[name](plane, params);
        _primitives.push(instance);
      }
    }
  }

  // ---- User Data (handlers & cleanup) --------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // dispose primitives
    for (const p of _primitives) {
      if (p && typeof p.cleanup === 'function') {
        p.cleanup();
      }
      if (p && p.timeline && typeof p.timeline.kill === 'function') {
        p.timeline.kill();
      }
    }
    // dispose material & geometry
    if (material && typeof material.dispose === 'function') material.dispose();
    if (geometry && typeof geometry.dispose === 'function') geometry.dispose();
    // dispose texture
    if (_texture && typeof _texture.dispose === 'function') _texture.dispose();
  };

  return root;
}
